#!/bin/sh
# Generated by Claude Code 2.1.330 (claude-opus-5-5)
# Build the Quest APK. Run from the repository root after `make sols` and
# android/build-deps.sh.
#
#   ANDROID_NDK_HOME  Android NDK r27c
#   ANDROID_HOME      Android SDK with build-tools 35.0.0 and platform 35
#   WORK              where build-deps.sh put its sources and prefix
#   JAVA, JAVAC       a JDK 17
set -eu

NDK=${ANDROID_NDK_HOME:?set ANDROID_NDK_HOME}
SDK=${ANDROID_HOME:?set ANDROID_HOME}
WORK=${WORK:-$HOME/.cache/neverball-quest}
DEPS=$WORK/prefix/android
SDL_SRC=$WORK/src/SDL
JAVA=${JAVA:-java}
JAVAC=${JAVAC:-javac}

BT=$SDK/build-tools/35.0.0
JAR=$SDK/platforms/android-35/android.jar
CC=$NDK/toolchains/llvm/prebuilt/linux-x86_64/bin/aarch64-linux-android29-clang
OUT=build-android

SRCS="$(sed -n '/^BALL_SRCS/,/^$/p' emscripten/ball.mk | tr -s ' \t\\' '\n' | grep '\.c$' |
        sed -e 's|share/audio_emscripten.c|share/audio.c share/fs_ov.c|' \
            -e 's|share/fetch_emscripten.c|share/fetch_null.c|' \
            -e 's|share/hmd_null.c|share/hmd_openxr.c|' \
            -e '/share\/tilt_null.c/d')"

rm -rf $OUT
mkdir -p $OUT/obj $OUT/apk/lib/arm64-v8a $OUT/assets $OUT/classes

# Native code

CFLAGS="-O2 -std=gnu99 -fPIC -Wall -DNDEBUG -DGL_GLEXT_PROTOTYPES -Ishare
        -I$DEPS/include -I$DEPS/include/SDL2 -I$DEPS/include/gl4es"
export CC CFLAGS OUT
echo "$SRCS" | xargs -P "$(nproc)" -n 1 sh -c \
    '$CC -c $CFLAGS -o $OUT/obj/$(echo $0 | tr / _ | sed "s/\.c\$/.o/") $0'

$CC -shared -o $OUT/apk/lib/arm64-v8a/libmain.so $OUT/obj/*.o \
    -L$DEPS/lib -lSDL2 -lSDL2_ttf -lfreetype -lvorbisfile -lvorbis -logg \
    -lpng16 -ljpeg -lgl4es -lopenxr_loader -lEGL -landroid -llog -lz -lm -ldl \
    -Wl,--no-undefined

cp $DEPS/lib/libSDL2.so $DEPS/lib/libopenxr_loader.so $OUT/apk/lib/arm64-v8a/
$NDK/toolchains/llvm/prebuilt/linux-x86_64/bin/llvm-strip --strip-unneeded $OUT/apk/lib/arm64-v8a/*.so

# Game data

(cd data && zip -q -r ../$OUT/assets/neverball-data.zip . -x '*.map')

# SDL's Java glue

$JAVAC -source 8 -target 8 -bootclasspath $JAR:$BT/core-lambda-stubs.jar -nowarn -d $OUT/classes \
    $SDL_SRC/android-project/app/src/main/java/org/libsdl/app/*.java
$JAVA -cp $BT/lib/d8.jar com.android.tools.r8.D8 --release --min-api 29 --lib $JAR \
    --output $OUT/apk $(find $OUT/classes -name '*.class')

# Package and sign

$BT/aapt2 link -o $OUT/unsigned.apk --manifest android/AndroidManifest.xml -I $JAR \
    --min-sdk-version 29 --target-sdk-version 32 --version-code 1 --version-name 1.7.0-quest \
    -A $OUT/assets -0 zip
(cd $OUT/apk && zip -q -r ../unsigned.apk classes.dex lib)
$BT/zipalign -f -p 4 $OUT/unsigned.apk $OUT/aligned.apk

KEY=${KEY:-$HOME/.android/neverball-quest}
if [ ! -f $KEY.pk8 ]; then
    mkdir -p $(dirname $KEY)
    openssl req -x509 -newkey rsa:2048 -nodes -days 10000 -subj '/CN=Neverball Quest' \
        -keyout $KEY.pem -out $KEY.x509.pem 2>/dev/null
    openssl pkcs8 -topk8 -nocrypt -outform DER -in $KEY.pem -out $KEY.pk8
fi
$JAVA -jar $BT/lib/apksigner.jar sign --key $KEY.pk8 --cert $KEY.x509.pem \
    --out neverball-quest.apk $OUT/aligned.apk

ls -l neverball-quest.apk
